use crate::configure::configure_app;

/// Whether this linked core was compiled with its conformance-suite feature.
pub const CONFORMANCE_SUITE_ENABLED: bool = cfg!(feature = "conformance-suite");

// `owns_logging = true`: AUCTIONEER installs this process's `log` sink, and
// `EdgeZero`'s `run_app` must not attempt a second one.
//
// There is exactly one sink per process — `log` permits one — and the
// boot sequence needs it installed BEFORE the memory envelope is
// validated, because the over-ceiling diagnostic is a warning and that
// warning is the whole safety margin of warn-not-refuse mode. So the
// sink has to be auctioneer's to install, and the adapter installs it at the
// top of `run`.
//
// Without this, the Fastly adapter never started. `run_app` calls
// `init_logger(...)?` when an endpoint is configured, which is
// `log::set_boxed_logger` — and it PROPAGATES `SetLoggerError` as a
// `fastly::Error`. auctioneer's boot had already installed a sink by then,
// so the second install failed and the error returned from `run_app`
// before routing, on every request. The flag is the ownership switch
// upstream provides for precisely this split.
//
// The adapter still installs the ENDPOINT sink when one is configured —
// see `auctioneer_adapter_fastly::install_boot_log` — so owning logging does
// not mean losing the platform channel. It means auctioneer chooses the sink
// and chooses when.
edgezero_core::app!(
    "../../edgezero.toml",
    configure = configure_app,
    owns_logging = true
);

#[cfg(test)]
use auctioneer_runtime::test_support::alloc_track::CountingAllocator;
#[cfg(test)]
use test_support::bidder_fixture;

#[cfg(test)]
#[global_allocator]
static TEST_ALLOCATOR: CountingAllocator = CountingAllocator;

#[cfg(test)]
mod build_feature_tests {
    use std::env::{VarError, current_exe, var};
    use std::process::{Command, Output};

    fn run_conformance_probe(expectation: Option<&str>) -> Output {
        let mut command = Command::new(current_exe().unwrap());
        command.args([
            "build_feature_tests::conformance_suite_indicator_",
            "--nocapture",
        ]);
        if let Some(expected) = expectation {
            command.env("AUCTIONEER__TEST__EXPECT_CONFORMANCE_SUITE", expected);
        } else {
            command.env_remove("AUCTIONEER__TEST__EXPECT_CONFORMANCE_SUITE");
        }
        let output = command.output().unwrap();
        let stdout = String::from_utf8_lossy(&output.stdout);
        assert!(stdout.contains("running 1 test"), "{stdout}");
        output
    }

    #[cfg(feature = "conformance-suite")]
    #[test]
    fn conformance_probe_rejects_accidentally_enabled_default_feature() {
        let output = run_conformance_probe(Some("disabled"));
        assert!(
            !output.status.success(),
            "default-mode expectation accepted an enabled conformance suite"
        );
    }

    #[cfg(not(feature = "conformance-suite"))]
    #[test]
    fn conformance_probe_rejects_missing_explicit_feature() {
        let output = run_conformance_probe(Some("enabled"));
        assert!(
            !output.status.success(),
            "conformance-mode expectation accepted a disabled conformance suite"
        );
    }

    #[test]
    fn conformance_probe_accepts_matching_explicit_expectation() {
        let expected = if super::CONFORMANCE_SUITE_ENABLED {
            "enabled"
        } else {
            "disabled"
        };
        let output = run_conformance_probe(Some(expected));
        assert!(
            output.status.success(),
            "{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn conformance_probe_accepts_unselected_mode() {
        let output = run_conformance_probe(None);
        assert!(
            output.status.success(),
            "{}{}",
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );
    }

    #[test]
    fn conformance_probe_rejects_invalid_expected_state() {
        for expected in ["", "true", "false", "enable", " disabled "] {
            let output = run_conformance_probe(Some(expected));
            assert!(
                !output.status.success(),
                "probe accepted invalid expected state {expected:?}"
            );
        }
    }

    #[test]
    fn conformance_suite_indicator_matches_expected_state() {
        let expected = match var("AUCTIONEER__TEST__EXPECT_CONFORMANCE_SUITE") {
            Ok(value) => match value.as_str() {
                "enabled" => true,
                "disabled" => false,
                _ => {
                    panic!("AUCTIONEER__TEST__EXPECT_CONFORMANCE_SUITE must be enabled or disabled")
                }
            },
            // Dedicated CI probes require explicit expectations; ordinary runs can unify features.
            Err(VarError::NotPresent) => super::CONFORMANCE_SUITE_ENABLED,
            Err(error) => panic!("invalid AUCTIONEER__TEST__EXPECT_CONFORMANCE_SUITE: {error}"),
        };
        let enabled = super::CONFORMANCE_SUITE_ENABLED;
        assert_eq!(
            enabled, expected,
            "compiled core conformance-suite feature must match the externally selected expectation"
        );
    }
}
